WITH unpacked AS (SELECT id, service, log_ts, status_code, payload_json, context['version'] AS version, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier FROM app_logs) SELECT DATE_TRUNC('HOUR', log_ts) AS hour_window, CASE WHEN status_code >= 422 THEN 'HIGH' ELSE 'LOW' END AS status_code_tier, SORT_ARRAY(COLLECT_SET(service)) AS service_list, COUNT(CASE WHEN service = 'search' THEN 1 END) AS search_count, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS duration_min, ROUND(AVG(status_code), 2) AS avg_status_code FROM unpacked GROUP BY ROLLUP (DATE_TRUNC('HOUR', log_ts), CASE WHEN status_code >= 422 THEN 'HIGH' ELSE 'LOW' END) HAVING duration_min < 1000000 ORDER BY status_code_tier DESC NULLS FIRST;
